//! Every spawnable ACF-3 item, extracted from the repo (lua/acf/entities)
//! by the catalogue script. Regenerate rather than edit. Each entry says
//! which entity class it spawns as, which paste-time key carries its ID,
//! and the numbers a builder chooses by.

#[derive(Debug, Clone, Copy)]
pub struct Item {
    pub entity: &'static str,
    pub key: &'static str,
    pub value: &'static str,
    pub category: &'static str,
    pub name: &'static str,
    pub model: &'static str,
    pub mass: Option<f64>,
    /// Guns: calibre range. Turrets: ring size range.
    pub range: Option<(f64, f64)>,
    /// Engines: fuel types it burns.
    pub fuels: &'static [&'static str],
    pub note: &'static str,
}

