/// Categories in drawer order, with counts.
pub fn categories() -> Vec<(&'static str, usize)> {
    let mut v: Vec<(&'static str, usize)> = Vec::new();
    for it in ITEMS {
        match v.iter_mut().find(|(c, _)| *c == it.category) {
            Some((_, n)) => *n += 1,
            None => v.push((it.category, 1)),
        }
    }
    v
}

/// Items whose category starts with `prefix` ("Engines", "Guns", …).
pub fn in_category(prefix: &str) -> Vec<&'static Item> {
    ITEMS.iter().filter(|i| i.category.starts_with(prefix)).collect()
}

/// An item by its paste value (engine ID, gearbox ID, weapon ID…).
pub fn find(value: &str) -> Option<&'static Item> {
    ITEMS.iter().find(|i| i.value.eq_ignore_ascii_case(value))
        .or_else(|| ITEMS.iter().find(|i| i.name.eq_ignore_ascii_case(value)))
}

/// Every catalogue model the game folder cannot show as it should: the
/// model is not there, it has no mesh, or its posed mesh pokes well outside
/// the bounds the model itself declares, which is what a wrongly assembled
/// or wrongly posed mesh does. Empty means every item can be drawn.
pub fn model_problems(lib: &mut crate::models::ModelLibrary) -> Vec<String> {
    // The plates a generated hull is made of are named by rule, not listed,
    // so they are checked here too.
    let mut plates = crate::hull::plate_models();
    plates.extend(crate::hull::triangle_models());
    let mut models: Vec<&str> = ITEMS.iter().map(|item| item.model).filter(|model| !model.is_empty()).collect();
    models.extend(plates.iter().map(String::as_str));
    models.sort_unstable();
    models.dedup();
    let mut problems = Vec::new();
    for model in models {
        let Some((bounds, _)) = lib.bounds(model) else {
            problems.push(format!("{model}: not in the game's files"));
            continue;
        };
        let Some(mesh) = lib.mesh(model) else {
            problems.push(format!("{model}: {}", lib.mesh_reason(model)));
            continue;
        };
        let (half, centre) = (bounds.half_extents(), bounds.centre());
        let (half, centre) = ([half.0, half.1, half.2], [centre.0, centre.1, centre.2]);
        let mut beyond = 0.0f64;
        for index in &mesh.indices {
            let at = mesh.positions[*index as usize];
            for axis in 0..3 {
                let slack = half[axis] * 0.2 + 5.0;
                beyond = beyond.max((at[axis] as f64 - centre[axis]).abs() - half[axis] - slack);
            }
        }
        if beyond > 0.0 {
            problems.push(format!("{model}: its mesh reaches {beyond:.1} units outside the model's own bounds"));
        }
    }
    problems
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_catalogue_covers_every_entity_class_the_references_use() {
        for cls in ["acf_engine", "acf_gearbox", "acf_gun", "acf_ammo", "acf_turret", "acf_turret_motor", "acf_turret_gyro", "acf_fueltank", "acf_crew", "acf_baseplate", "acf_controller", "acf_radar", "acf_rack"] {
            assert!(ITEMS.iter().any(|i| i.entity == cls), "{cls}");
        }
        assert!(ITEMS.len() > 200);
        assert_eq!(find("CVT-T").map(|i| i.entity), Some("acf_gearbox"));
        assert_eq!(find("6.5-I6").map(|i| i.fuels), Some(&["Diesel"][..]), "the reference tanks run diesel I6s");
        let c = find("C").unwrap();
        assert_eq!(c.range, Some((20.0, 170.0)));
        assert!(!categories().is_empty());
    }

    #[test]
    fn every_item_has_a_model_the_game_can_spawn() {
        for it in ITEMS {
            assert!(!it.model.is_empty(), "{} ({}) has no model", it.name, it.value);
        }
    }

    #[test]
    fn every_wiremod_part_has_ports_the_node_view_can_show() {
        // Four Wiremod parts have no wire ports at all: they are read or
        // found by other parts, not wired.
        let passive = ["gmod_wire_locator", "gmod_wire_cd_disk", "gmod_wire_data_satellitedish", "gmod_wire_data_store"];
        let unknown: Vec<&str> = ITEMS
            .iter()
            .filter(|item| item.category.starts_with("Wire"))
            .filter(|item| crate::ports::of_class(item.entity).is_none() && !passive.contains(&item.entity))
            .map(|item| item.entity)
            .collect();
        assert!(unknown.is_empty(), "{unknown:?}");
    }
}
